import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        timestamp = time.time()
        if platform.system() == "Windows":
            cpu_usage = subprocess.check_output(
                ['wmic', 'cpu', 'get', 'loadpercentage'],
                shell=True
            ).decode().split()[-2]
        else:
            cpu_usage = subprocess.check_output(
                ['top', '-bn1'],
                shell=True
            ).decode().split('\n')[2].split()[1].replace(',', '.')
        data.append({"timestamp": timestamp, "cpu_usage": float(cpu_usage)})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

